package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class TakeStatement {
    // Records the person's due-total now and binds each of their counting claims (their open claims within a hold and not bound do not count) to its figure now;
    // the rest of their claims are left unbound. The late charge is never bound: the due-total includes it,
    // but each claim is bound to the figure under it.
    public void take(@Val Person person, Claims claims, Rates rates, Settings settings, Sheets sheets, Statements statements,
            Out<Statement> statementOut) {
        statements.lock(person.id());
        LocalDate today = sheets.today(person.sheetId());
        Map<Long, BigDecimal> figures = new LinkedHashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.list(person.sheetId())) {
            if (claim.personId() == person.id()
                    && (claim.status() == ClaimStatus.SETTLED || (claim.status().isOpen() && Rollup.counts(claim, person)))) {
                BigDecimal figure = figure(claim, person, rates, settings);
                figures.put(claim.id(), figure);
                BigDecimal due = claim.settledDue() != null ? figure : settings.withLate(claim, figure, today);
                if (due != null) {
                    total = total.add(due);
                }
            }
        }
        // With no rate today and no figure, the due-total is n/a.
        boolean none = rates.on(person.sheetId(), person.gradeOn(today), today) == null
                && figures.values().stream().allMatch(Objects::isNull);
        claims.bind(person.sheetId(), person.id(), figures);
        Statement statement = new Statement(person.sheetId(), person.id(), none ? "n/a" : total.toPlainString(),
                figures.size(), today);
        statements.add(statement);
        statementOut.set(statement);
    }

    /**
     * The claim's figure now (null when it has none): a settled claim's frozen due, otherwise the figure the
     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, rounded by the policy date, raised to the floor.
     */
    private static BigDecimal figure(Claim claim, Person person, Rates rates, Settings settings) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
        return settings.live(claim, rate);
    }
}
package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditStatement {
    public void audit(@Val Person person, @Val Statement statement, ServerHttpConnection connection, Audit audit) {
        audit.record(Audit.line("STATEMENT", person.sheetId(), Audit.user(connection), "name=" + person.name(),
                "due-total=" + statement.dueTotal(), "claims=" + statement.claims()));
    }
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { claimsKey } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { useUser } from '../session/useUser';
import { statementsKey, statementsQuery } from './statementsQuery';
import type { Statements } from './statementsQuery';

/**
 * A person's statements and the button that takes one: it records their due-total now and binds each of
 * their counting claims to its figure now, until their next statement.
 */
function PersonStatement({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useState('');
  const once = useSubmitOnce();
  const shown = (useQuery(statementsQuery(sheetId)).data ?? []).find((s) => s.personId === personId);
  const take = useMutation({
    mutationFn: () =>
      postJson<Statements>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`, {}, user),
    // The claims are re-read first, so the count moves on only once the bound figures show.
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) });
    },
    onError: () => setError('The statement could not be taken.'),
  });

  return (
    <td>
      <span data-testid="person-statement-count">{shown?.count ?? 0}</span>{' '}
      <span data-testid="person-stated-total">{shown?.dueTotal ?? ''}</span>{' '}
      <span data-testid="person-statement-date">{shown?.date ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          setError('');
          once(() => take.mutateAsync());
        }}
      >
        Statement
      </button>
      {error && <span data-testid="person-error">{error}</span>}
    </td>
  );
}

/** Whether the person's last statement bound the claim to its figure. */
function ClaimStated({ claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-stated">{claim.stated ? 'yes' : 'no'}</td>;
}

export const contributions = [
  PersonHeaders.fill({ order: 17, Component: () => <th>Statements</th> }),
  PersonCells.fill({ order: 17, Component: PersonStatement }),
  ClaimCells.fill({ order: 15, Component: ClaimStated }),
];
